      "id": 3,
      "claim": "The total runtime of the whole series is about 5,500 hours (≈229 days).",
      "evidence": "11,000 episodes × 0.5 h per episode = 5,500 h.",
      "weight": 0.25,
      "depends_on": [1, 2]
    },
